using Microsoft.Data.Sqlite;namespace OncaPDV.Infrastructure;public sealed record Report022(int Sales,decimal Revenue,decimal Cash,decimal Pix,decimal Debit,decimal Credit,decimal StoreCredit,decimal CreditReceipts,int PaidOrders,int CancelledSales);public sealed class ReportService022{private readonly OncaDatabase _db;public ReportService022(OncaDatabase db){_db=db;}public async Task<Report022> LoadAsync(DateTimeOffset from,DateTimeOffset to,CancellationToken ct=default){var baseSummary=await new FinalFeaturesService(_db).SummaryAsync(from,to,ct);await using var c=_db.Open();async Task<int>I(string sql){await using var q=c.CreateCommand();q.CommandText=sql;q.Parameters.AddWithValue("$f",from.ToString("O"));q.Parameters.AddWithValue("$t",to.ToString("O"));return Convert.ToInt32(await q.ExecuteScalarAsync(ct));}var cancelled=await I("SELECT COUNT(*) FROM sales WHERE status='Cancelled' AND created_at >= $f AND created_at < $t");var orders=await new OrderService022(_db).CountPaidAsync(from,to,ct);return new(baseSummary.Sales,baseSummary.Revenue,baseSummary.Cash,baseSummary.Pix,baseSummary.Debit,baseSummary.Credit,baseSummary.StoreCredit,baseSummary.CreditReceipts,orders,cancelled);}public async Task<string> PdfAsync(Report022 r,DateTimeOffset from,DateTimeOffset to,AppPaths paths,CancellationToken ct=default){paths.EnsureCreated();var lines=new[]{"ONÇA PRODUTOS DE LIMPEZA","RELATÓRIO GERENCIAL",$"Período: {from:dd/MM/yyyy} a {to.AddDays(-1):dd/MM/yyyy}",$"Emitido em: {DateTime.Now:dd/MM/yyyy HH:mm}","",$"VENDAS CONCLUÍDAS: {r.Sales}",$"FATURAMENTO: {r.Revenue:C}",$"PEDIDOS PAGOS: {r.PaidOrders}",$"CANCELAMENTOS: {r.CancelledSales}","","FORMAS DE PAGAMENTO",$"Dinheiro: {r.Cash:C}",$"PIX: {r.Pix:C}",$"Débito: {r.Debit:C}",$"Crédito: {r.Credit:C}",$"Crediário gerado: {r.StoreCredit:C}",$"Crediário recebido: {r.CreditReceipts:C}","","Página 1 de 1","ONÇA PDV PRO • v0.1.22"};var file=Path.Combine(paths.Exports,$"relatorio-onca-{DateTime.Now:yyyyMMdd-HHmmssfff}.pdf");await F